  private static Object data(IPersistentMap map, Class<?> expected, Type[] arguments, Map<TypeVariable<?>, Type> bound) {
    Class<?> record;
    var tag = map.valAt(TAG);
    if (expected.isRecord()) {
      record = expected;
    } else if (tag instanceof Keyword keyword) {
      record = classOfTag(keyword);
      if (!expected.isAssignableFrom(record))
        throw new IllegalArgumentException(keyword + " is not a " + expected.getSimpleName());
    } else {
      throw new IllegalArgumentException("a " + expected.getSimpleName() + " needs a :lawspec/tag: " + RT.printString(map));
    }
    var variables = new HashMap<TypeVariable<?>, Type>(bound);
    TypeVariable<?>[] own = expected.getTypeParameters();
    for (int i = 0; i < own.length && i < arguments.length; i++) variables.put(own[i], arguments[i]);
    if (record != expected) {
      // A case's type parameters are its sum's, by the sum it implements.
      for (Type implemented : record.getGenericInterfaces())
        if (implemented instanceof ParameterizedType p && p.getRawType() == expected) {
          Type[] actual = p.getActualTypeArguments();
          for (int i = 0; i < actual.length && i < own.length; i++)
            if (actual[i] instanceof TypeVariable<?> v && variables.containsKey(own[i])) variables.put(v, variables.get(own[i]));
        }
    }
    RecordComponent[] components = record.getRecordComponents();
    var types = new Class<?>[components.length];
    var values = new Object[components.length];
    for (int i = 0; i < components.length; i++) {
      types[i] = components[i].getType();
      var key = Keyword.intern(kebab(components[i].getName()));
      if (!map.containsKey(key) && !(components[i].getType() == LawSpecRuntime.Maybe.class))
        throw new IllegalArgumentException(tagOf(record) + " needs " + key + ": " + RT.printString(map));
      values[i] = toJava(map.valAt(key), components[i].getGenericType(), variables);
    }
    try {
      Constructor<?> constructor = record.getDeclaredConstructor(types);
      constructor.setAccessible(true);
      return constructor.newInstance(values);
    } catch (ReflectiveOperationException e) {
      throw new IllegalArgumentException("cannot make " + tagOf(record) + ": " + e, e);
    }
  }

  private static Object number(Object value, Class<?> type) {
    if (value instanceof Character c && (type == char.class || type == Character.class)) return c;
    if (!(value instanceof Number n)) throw new IllegalArgumentException("expected a number, not " + RT.printString(value));
    if (type == int.class || type == Integer.class) return Math.toIntExact(exact(n).longValueExact());
    if (type == long.class || type == Long.class) return exact(n).longValueExact();
    if (type == short.class || type == Short.class) return exact(n).shortValueExact();
    if (type == byte.class || type == Byte.class) return exact(n).byteValueExact();
    if (type == double.class || type == Double.class) return n.doubleValue();
    if (type == float.class || type == Float.class) return n.floatValue();
    if (type == BigInteger.class) return exact(n);
    if (type == BigDecimal.class) {
      if (n instanceof BigDecimal d) return d;
      if (n instanceof Ratio r) return r.decimalValue();
      return new BigDecimal(exact(n));
    }
    return n;
  }

  private static BigInteger exact(Number n) {
    if (n instanceof BigInteger b) return b;
    if (n instanceof BigInt b) return b.toBigInteger();
    if (n instanceof Long || n instanceof Integer || n instanceof Short || n instanceof Byte) return BigInteger.valueOf(n.longValue());
    if (n instanceof BigDecimal d) return d.toBigIntegerExact();
    throw new IllegalArgumentException("expected an integer, not " + n);
  }

  private static Class<?> raw(Type type, Map<TypeVariable<?>, Type> bound) {
    if (type instanceof Class<?> c) return c;
    if (type instanceof ParameterizedType p) return (Class<?>) p.getRawType();
    if (type instanceof TypeVariable<?> v && bound.containsKey(v)) return raw(bound.get(v), bound);
    if (type instanceof GenericArrayType a) return Array.newInstance(raw(a.getGenericComponentType(), bound), 0).getClass();
    return Object.class;
  }

  private static List<Object> items(Object value) {
    var out = new ArrayList<Object>();
    if (value == null) return out;
    if (value instanceof Collection<?> c) {
      out.addAll(c);
      return out;
    }
    if (value.getClass().isArray()) {
      for (int i = 0; i < Array.getLength(value); i++) out.add(Array.get(value, i));
      return out;
    }
    for (ISeq s = RT.seq(value); s != null; s = s.next()) out.add(s.first());
    return out;
  }

  private static Object deref(Object value) {
    try {
      return value instanceof Future<?> f ? f.get() : ((IDeref) value).deref();
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new IllegalStateException(e);
    } catch (Exception e) {
      Throwable cause = e instanceof java.util.concurrent.ExecutionException ? e.getCause() : e;
      if (cause instanceof ExceptionInfo info) throw failure(info);
      throw rethrow(cause);
    }
  }

  // Calls ----------------------------------------------------------------

  /** A Clojure function, its namespace loaded once. */
  public static IFn var(String namespace, String name) {
    return VARS.computeIfAbsent(namespace + "/" + name, key -> {
      synchronized (REQUIRE) {
        REQUIRE.invoke(Clojure.read(namespace));
      }
      return Clojure.var(namespace, name);
    });
  }

  private static Method method(Class<?> owner, String name) {
    return METHODS.computeIfAbsent(List.of(owner, name), key -> {
      for (Method m : owner.getMethods()) if (m.getName().equals(name)) return m;
      for (Method m : owner.getDeclaredMethods()) if (m.getName().equals(name)) return m;
      throw new IllegalArgumentException("no method " + name + " in " + owner.getName());
    });
  }

  /** A bridge method's call of its Clojure adapter: arguments in, the result back by the bridge's type. */
  public static Object invoke(Class<?> bridge, String method, String namespace, String function, Object... arguments) {
    Method m = method(bridge, method);
    return result(m, () -> apply(var(namespace, function), arguments));
  }

  /** A handler of a Clojure handler map: the map the adapter's function makes. */
  public static Object handler(String namespace, String function, Object... arguments) {
    var converted = new Object[arguments.length];
    for (int i = 0; i < arguments.length; i++) converted[i] = toClojure(arguments[i]);
    Object made = var(namespace, function).applyTo(RT.seq(converted));
    if (!(made instanceof IPersistentMap)) throw new IllegalArgumentException(namespace + "/" + function + " must return a map of operations");
    return made;
  }

  /** A bridge handler's operation: the function its map holds for it. */
  public static Object operation(Object handler, Class<?> bridge, String method, String key, Object... arguments) {
    Method m = method(bridge, method);
    Object operation = ((IPersistentMap) handler).valAt(Keyword.intern(key));
    if (!(operation instanceof IFn f)) throw new IllegalArgumentException("the handler has no " + key + " operation");
    return result(m, () -> apply(f, arguments));
  }

  private static Object apply(IFn f, Object[] arguments) {
    var converted = new Object[arguments.length];
    for (int i = 0; i < arguments.length; i++) converted[i] = toClojure(arguments[i]);
    return f.applyTo(RT.seq(converted));
  }

  private static Object result(Method m, java.util.function.Supplier<Object> call) {
    Object value;
    try {
      value = call.get();
    } catch (ExceptionInfo info) {
      throw failure(info);
    }
    return toJava(value, m.getGenericReturnType());
  }

  /** An ex-info with :lawspec/failure as the model's failure. */
  public static RuntimeException failure(ExceptionInfo info) {
    var data = info.getData();
    if (data != null && data.containsKey(FAILURE)) return new LawSpecRuntime.Fail(untyped(data.valAt(FAILURE)));
    return info;
  }

  /** An operation of an ability handler, called from Clojure with Clojure data. */
  public static Object call(Object handler, String operation, Object... arguments) {
    String name = camel(operation, false);
    for (Method m : handler.getClass().getMethods()) {
      if (!m.getName().equals(name) || m.getParameterCount() != arguments.length) continue;
      var converted = new Object[arguments.length];
      Type[] types = m.getGenericParameterTypes();
      for (int i = 0; i < arguments.length; i++) converted[i] = toJava(arguments[i], types[i]);
      try {
        m.setAccessible(true);
        return toClojure(m.invoke(handler, converted));
      } catch (java.lang.reflect.InvocationTargetException e) {
        throw rethrow(e.getCause());
      } catch (IllegalAccessException e) {
        throw new IllegalStateException(e);
      }
    }
    throw new IllegalArgumentException(handler.getClass().getName() + " has no operation " + operation);
  }

  /** A static method of the model (a checked definition), called with Clojure data. */
  public static Object callStatic(Class<?> owner, String name, Object... arguments) {
    Method m = method(owner, name);
    Type[] types = m.getGenericParameterTypes();
    var converted = new Object[arguments.length];
    for (int i = 0; i < arguments.length; i++) converted[i] = toJava(arguments[i], types[i]);
    try {
      return toClojure(m.invoke(null, converted));
    } catch (java.lang.reflect.InvocationTargetException e) {
      throw rethrow(e.getCause());
    } catch (IllegalAccessException e) {
      throw new IllegalStateException(e);
    }
  }

  private static RuntimeException rethrow(Throwable t) {
    if (t instanceof RuntimeException r) return r;
    if (t instanceof Error e) throw e;
    return new RuntimeException(t);
  }
